import { runBenchmark } from './measure.mjs'
import { pathToFileURL } from 'node:url'

export const PROJECT_MEDIAN_GATE_MS = 60

export function gateDecision(valueMs, limitMs = PROJECT_MEDIAN_GATE_MS) {
  return {
    gate: 'project report median latency',
    valueMs,
    limitMs,
    passed: valueMs <= limitMs,
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const result = await runBenchmark()
  const decision = gateDecision(result.medianMs)
  console.log(JSON.stringify(decision, null, 2))
  if (!decision.passed) process.exitCode = 1
}
import { buildReport, createInventory } from './src/report.mjs'

const items = createInventory()
const counts = {
  seenScans: 0,
  regionFilters: 0,
  regionCandidates: 0,
  profileEntries: 0,
}

buildReport(items, {
  onSeenScan: () => {
    counts.seenScans += 1
  },
  onRegionFilter: () => {
    counts.regionFilters += 1
  },
  onRegionReduce: (length) => {
    counts.regionCandidates += length
  },
  onProfile: () => {
    counts.profileEntries += 1
  },
})

console.log(JSON.stringify({ inventoryRows: items.length, ...counts }, null, 2))

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { buildReport } from '../src/report.mjs'

test('report removes duplicate product-region rows and sorts by share then identity', () => {
  const items = [
    { productId: 'b', region: 'north', warehouse: 'one', units: 4 },
    { productId: 'a', region: 'north', warehouse: 'two', units: 4 },
    { productId: 'a', region: 'north', warehouse: 'three', units: 4 },
    { productId: 'c', region: 'south', warehouse: 'one', units: 2 },
  ]
  const report = buildReport(items)
  assert.deepEqual(
    report.map(({ productId, region }) => `${productId}:${region}`),
    ['c:south', 'a:north', 'b:north'],
  )
  assert.equal(report.length, 3)
  assert.deepEqual(Object.keys(report[0]), ['productId', 'region', 'units', 'share'])
})
import { performance } from 'node:perf_hooks'
import { startReportServer } from './server.mjs'

export async function runBenchmark({ warmups = 2, measured = 7 } = {}) {
  const { server, url } = await startReportServer()
  try {
    const warmupSamples = []
    for (let index = 0; index < warmups; index += 1) {
      const start = performance.now()
      await fetch(`${url}/report`).then((response) => response.arrayBuffer())
      warmupSamples.push(Number((performance.now() - start).toFixed(3)))
    }

    const samplesMs = []
    for (let index = 0; index < measured; index += 1) {
      const start = performance.now()
      const response = await fetch(`${url}/report`)
      const body = await response.arrayBuffer()
      if (!response.ok || body.byteLength === 0) throw new Error('report request failed')
      samplesMs.push(Number((performance.now() - start).toFixed(3)))
    }

    const ordered = [...samplesMs].sort((left, right) => left - right)
    const percentile = ordered[Math.min(ordered.length - 1, Math.floor(ordered.length * 0.95))]
    return {
      clock: 'performance.now around one complete GET /report and body read',
      state: 'warm process and warm HTTP server; request and body are included',
      warmupSamplesMs: warmupSamples,
      samplesMs,
      medianMs: ordered[Math.floor(ordered.length / 2)],
      p95Ms: percentile,
    }
  } finally {
    await new Promise((resolve) => server.close(resolve))
  }
}
